-- Fixed typed financial read projections and one shared fragment capture engine.
BEGIN;
DO $$BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_content_capture_v1(uuid)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM '9cc2ee9cc62bc7a7299835b6b1f33089e7e1fea7e518144839af1c141e30baa9' THEN RAISE EXCEPTION 'tenant_content_capture_prior_source_changed';END IF;END $$;
CREATE FUNCTION public.sandy_tenant_financial_manifest_v1() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$ SELECT $m${"id":"customer_financial_fragments_v1","format_version":"1.0.0","project_ref":"zmqlyygzqoidkcwdysok","complete_tenant_coverage":false,"external_provider_assets_included":false,"erasure_supported":false,"restore_supported":false,"provider_verified":false,"payment_executed":false,"financial_source":"internal_commerce_records","fragment_encoding":"ndjson_contiguous_unicode_parts_with_per_row_sha256_chain","fragment_characters":65536,"maximum_row_bytes":16777216,"maximum_total_plaintext_bytes":134217728,"maximum_fragments":2048,"maximum_rows_per_table":50000,"tables":[{"table":"sandy_commerce_configuration","owner_column":"customer_id","order":["customer_id"],"columns":[{"name":"customer_id","type":"uuid","nullable":false},{"name":"currency","type":"text","nullable":false},{"name":"minor_unit_exponent","type":"integer","nullable":false},{"name":"invoice_prefix","type":"text","nullable":false},{"name":"next_invoice_number","type":"bigint","nullable":false,"encoding":"decimal_integer_string"},{"name":"default_terms_days","type":"integer","nullable":false},{"name":"version","type":"integer","nullable":false},{"name":"created_at","type":"timestamp with time zone","nullable":false},{"name":"updated_at","type":"timestamp with time zone","nullable":false}],"excluded_columns":[]},{"table":"sandy_commerce_consents","owner_column":"customer_id","order":["customer_id"],"columns":[{"name":"customer_id","type":"uuid","nullable":false},{"name":"terms_version","type":"text","nullable":false},{"name":"invoice_forwarding_allowed","type":"boolean","nullable":false},{"name":"automatic_renewal_recorded","type":"boolean","nullable":false},{"name":"expires_at","type":"timestamp with time zone","nullable":false},{"name":"revoked_at","type":"timestamp with time zone","nullable":true},{"name":"revision","type":"integer","nullable":false},{"name":"updated_at","type":"timestamp with time zone","nullable":false}],"excluded_columns":[]},{"table":"sandy_commerce_accounts","owner_column":"customer_id","order":["id"],"columns":[{"name":"id","type":"uuid","nullable":false},{"name":"customer_id","type":"uuid","nullable":false},{"name":"code","type":"text","nullable":false},{"name":"name","type":"text","nullable":false},{"name":"kind","type":"text","nullable":false},{"name":"currency","type":"text","nullable":false},{"name":"minor_unit_exponent","type":"integer","nullable":false},{"name":"active","type":"boolean","nullable":false},{"name":"version","type":"integer","nullable":false},{"name":"created_at","type":"timestamp with time zone","nullable":false},{"name":"updated_at","type":"timestamp with time zone","nullable":false}],"excluded_columns":[]},{"table":"sandy_commerce_entries","owner_column":"customer_id","order":["id"],"columns":[{"name":"id","type":"uuid","nullable":false},{"name":"customer_id","type":"uuid","nullable":false},{"name":"description","type":"text","nullable":false},{"name":"external_reference","type":"text","nullable":false},{"name":"effective_at","type":"timestamp with time zone","nullable":false},{"name":"state","type":"text","nullable":false},{"name":"currency","type":"text","nullable":false},{"name":"minor_unit_exponent","type":"integer","nullable":false},{"name":"version","type":"integer","nullable":false},{"name":"reversal_of","type":"uuid","nullable":true},{"name":"posted_at","type":"timestamp with time zone","nullable":true},{"name":"created_at","type":"timestamp with time zone","nullable":false},{"name":"updated_at","type":"timestamp with time zone","nullable":false}],"excluded_columns":[]},{"table":"sandy_commerce_entry_lines","owner_column":"entry_id","order":["id"],"columns":[{"name":"id","type":"uuid","nullable":false},{"name":"entry_id","type":"uuid","nullable":false},{"name":"account_id","type":"uuid","nullable":false},{"name":"debit_minor","type":"bigint","nullable":false,"encoding":"decimal_integer_string"},{"name":"credit_minor","type":"bigint","nullable":false,"encoding":"decimal_integer_string"},{"name":"description","type":"text","nullable":false}],"excluded_columns":[],"ownership_adapter":"financial_entry_customer"},{"table":"sandy_commerce_statements","owner_column":"customer_id","order":["id"],"columns":[{"name":"id","type":"uuid","nullable":false},{"name":"customer_id","type":"uuid","nullable":false},{"name":"account_id","type":"uuid","nullable":false},{"name":"source_reference","type":"text","nullable":false},{"name":"source_kind","type":"text","nullable":false},{"name":"content_sha256","type":"text","nullable":false},{"name":"created_at","type":"timestamp with time zone","nullable":false}],"excluded_columns":[]},{"table":"sandy_commerce_statement_lines","owner_column":"statement_id","order":["id"],"columns":[{"name":"id","type":"uuid","nullable":false},{"name":"statement_id","type":"uuid","nullable":false},{"name":"external_reference","type":"text","nullable":false},{"name":"effective_at","type":"timestamp with time zone","nullable":false},{"name":"amount_minor","type":"bigint","nullable":false,"encoding":"decimal_integer_string"},{"name":"description","type":"text","nullable":false}],"excluded_columns":[],"ownership_adapter":"financial_statement_customer"},{"table":"sandy_commerce_reconciliations","owner_column":"customer_id","order":["id"],"columns":[{"name":"id","type":"uuid","nullable":false},{"name":"customer_id","type":"uuid","nullable":false},{"name":"statement_id","type":"uuid","nullable":false},{"name":"state","type":"text","nullable":false},{"name":"matches","type":"jsonb","nullable":false,"encoding":"strict_reconciliation_matches"},{"name":"version","type":"integer","nullable":false},{"name":"reviewed_at","type":"timestamp with time zone","nullable":true},{"name":"created_at","type":"timestamp with time zone","nullable":false}],"excluded_columns":[]},{"table":"sandy_commerce_invoices","owner_column":"customer_id","order":["id"],"columns":[{"name":"id","type":"uuid","nullable":false},{"name":"customer_id","type":"uuid","nullable":false},{"name":"counterparty_name","type":"text","nullable":false},{"name":"external_reference","type":"text","nullable":false},{"name":"currency","type":"text","nullable":false},{"name":"minor_unit_exponent","type":"integer","nullable":false},{"name":"items","type":"jsonb","nullable":false,"encoding":"strict_invoice_items"},{"name":"subtotal_minor","type":"numeric(30,0)","nullable":false,"encoding":"decimal_integer_string"},{"name":"tax_minor","type":"bigint","nullable":false,"encoding":"decimal_integer_string"},{"name":"discount_minor","type":"bigint","nullable":false,"encoding":"decimal_integer_string"},{"name":"total_minor","type":"numeric(30,0)","nullable":false,"encoding":"decimal_integer_string"},{"name":"due_at","type":"timestamp with time zone","nullable":false},{"name":"state","type":"text","nullable":false},{"name":"invoice_number","type":"text","nullable":true},{"name":"version","type":"integer","nullable":false},{"name":"source_message_id","type":"uuid","nullable":true},{"name":"forwarding_status","type":"text","nullable":false},{"name":"payment_status","type":"text","nullable":false},{"name":"created_at","type":"timestamp with time zone","nullable":false},{"name":"updated_at","type":"timestamp with time zone","nullable":false}],"excluded_columns":[]},{"table":"sandy_commerce_entitlements","owner_column":"customer_id","order":["id"],"columns":[{"name":"id","type":"uuid","nullable":false},{"name":"customer_id","type":"uuid","nullable":false},{"name":"feature_key","type":"text","nullable":false},{"name":"expires_at","type":"timestamp with time zone","nullable":false},{"name":"revoked_at","type":"timestamp with time zone","nullable":true},{"name":"reason","type":"text","nullable":false},{"name":"version","type":"integer","nullable":false},{"name":"updated_at","type":"timestamp with time zone","nullable":false}],"excluded_columns":[]}],"references":[{"table":"email_messages","columns":[{"name":"id","type":"uuid","nullable":false},{"name":"customer_id","type":"uuid","nullable":false}]}],"excluded_resources":["sandy_commerce_plans","sandy_commerce_prices","sandy_commerce_contracts","sandy_commerce_results","sandy_commerce_effects","sandy_product_mutation_evidence"],"schema_sha256":"ac5691a58acaf456d1490c0ea45f0f1bd8ce1ae37592f8574da1388cac336380","manifest_sha256":"ccac4b06066c1f9ed0613d47e00e6abc85075063a29ce26f9b82f11fe43eaeb1"}$m$::jsonb $$;
CREATE FUNCTION public.sandy_tenant_financial_schema_sha256() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
WITH selected AS(SELECT item,t.ordinality,n.oid AS ns,c.oid,c.relowner,c.relrowsecurity,c.relforcerowsecurity,c.relkind FROM jsonb_array_elements(((public.sandy_tenant_financial_manifest_v1()->'tables')||(public.sandy_tenant_financial_manifest_v1()->'references'))) WITH ORDINALITY t(item,ordinality) JOIN pg_namespace n ON n.nspname='public' JOIN pg_class c ON c.relnamespace=n.oid AND c.relname=t.item->>'table'),document AS(SELECT jsonb_agg(jsonb_build_object('table',s.item->>'table','owner',pg_get_userbyid(s.relowner),'kind',s.relkind,'rls',s.relrowsecurity,'force_rls',s.relforcerowsecurity,'columns',(SELECT jsonb_agg(jsonb_build_object('name',expected.item->>'name','type',format_type(a.atttypid,a.atttypmod),'nullable',NOT a.attnotnull,'generated',a.attgenerated,'identity',a.attidentity,'expression',CASE WHEN a.attgenerated<>'' THEN pg_get_expr(d.adbin,d.adrelid) ELSE NULL END) ORDER BY expected.ordinality) FROM jsonb_array_elements(s.item->'columns') WITH ORDINALITY expected(item,ordinality) LEFT JOIN pg_attribute a ON a.attrelid=s.oid AND a.attname=expected.item->>'name' AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum)) ORDER BY s.ordinality) value FROM selected s) SELECT encode(extensions.digest(value::text,'sha256'),'hex') FROM document
$$;
CREATE FUNCTION public.sandy_tenant_financial_json_valid(p_table text,p_document jsonb,p_tenant uuid,p_parent uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE item jsonb;line public.sandy_commerce_statement_lines;number_text text;key_count integer;
BEGIN
 IF jsonb_typeof(p_document) IS DISTINCT FROM 'array' THEN RETURN false;END IF;
 IF p_table='sandy_commerce_invoices' THEN
  IF jsonb_array_length(p_document) NOT BETWEEN 1 AND 50 THEN RETURN false;END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_document) LOOP
   IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN RETURN false;END IF;
   SELECT count(*) INTO key_count FROM jsonb_object_keys(item);
   IF key_count<>3 OR NOT item ?& ARRAY['description','quantity','unit_minor'] OR jsonb_typeof(item->'description') IS DISTINCT FROM 'string' OR char_length(item->>'description') NOT BETWEEN 1 AND 1000 OR jsonb_typeof(item->'quantity') IS DISTINCT FROM 'number' OR item->>'quantity' !~ '^[1-9][0-9]{0,5}$' OR (item->>'quantity')::numeric>100000 OR jsonb_typeof(item->'unit_minor') IS DISTINCT FROM 'string' OR item->>'unit_minor' !~ '^(0|[1-9][0-9]{0,18})$' OR (item->>'unit_minor')::numeric>9223372036854775807 THEN RETURN false;END IF;
  END LOOP;
 ELSIF p_table='sandy_commerce_reconciliations' THEN
  IF jsonb_array_length(p_document)>50000 THEN RETURN false;END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_document) LOOP
   IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN RETURN false;END IF;
   SELECT count(*) INTO key_count FROM jsonb_object_keys(item);
   IF key_count<>7 OR NOT item ?& ARRAY['statement_line_id','external_reference','amount_minor','state','candidate_count','candidate_entry_id','provider_verified'] OR jsonb_typeof(item->'statement_line_id') IS DISTINCT FROM 'string' OR item->>'statement_line_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR jsonb_typeof(item->'external_reference') IS DISTINCT FROM 'string' OR char_length(item->>'external_reference')>100000 OR jsonb_typeof(item->'amount_minor') IS DISTINCT FROM 'string' OR item->>'amount_minor' !~ '^-?(0|[1-9][0-9]{0,18})$' OR jsonb_typeof(item->'state') IS DISTINCT FROM 'string' OR item->>'state' NOT IN('proposed_internal_match','ambiguous','unmatched') OR jsonb_typeof(item->'candidate_count') IS DISTINCT FROM 'number' OR item->>'candidate_count' !~ '^(0|[1-9][0-9]{0,9})$' OR (item->>'candidate_count')::numeric>2147483647 OR item->'provider_verified' IS DISTINCT FROM 'false'::jsonb OR jsonb_typeof(item->'candidate_entry_id') NOT IN('string','null') THEN RETURN false;END IF;
   SELECT l.* INTO line FROM public.sandy_commerce_statement_lines l JOIN public.sandy_commerce_statements s ON s.id=l.statement_id AND s.customer_id=p_tenant WHERE l.id=(item->>'statement_line_id')::uuid AND l.statement_id=p_parent;
   IF line.id IS NULL OR line.external_reference IS DISTINCT FROM item->>'external_reference' OR line.amount_minor::text IS DISTINCT FROM item->>'amount_minor' THEN RETURN false;END IF;
   IF item->>'candidate_entry_id' IS NOT NULL THEN
    IF item->>'candidate_entry_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR NOT EXISTS(SELECT 1 FROM public.sandy_commerce_entries e WHERE e.id=(item->>'candidate_entry_id')::uuid AND e.customer_id=p_tenant) THEN RETURN false;END IF;
   END IF;
  END LOOP;
 ELSE RETURN false;
 END IF;
 RETURN true;
EXCEPTION WHEN data_exception THEN RETURN false;
END $$;
CREATE FUNCTION public.sandy_tenant_fragment_capture_v1(p_tenant uuid,p_manifest text) RETURNS SETOF jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $$
DECLARE manifest jsonb:=CASE p_manifest WHEN 'customer_content_fragments_v1' THEN public.sandy_tenant_content_manifest_v1() WHEN 'customer_financial_fragments_v1' THEN public.sandy_tenant_financial_manifest_v1() ELSE NULL END;entry jsonb;col jsonb;projection text;size_sql text;query text;row_data record;stream_buffer text;row_text text;row_chain text;sequence_number integer:=0;table_sequence integer;table_rows integer;row_count integer;owner_predicate text;order_sql text;total_bytes bigint:=0;oversize boolean;
BEGIN
 IF p_tenant IS NULL OR manifest IS NULL OR (CASE p_manifest WHEN 'customer_content_fragments_v1' THEN public.sandy_tenant_content_schema_sha256() WHEN 'customer_financial_fragments_v1' THEN public.sandy_tenant_financial_schema_sha256() END) IS DISTINCT FROM manifest->>'schema_sha256' THEN RAISE EXCEPTION 'tenant_content_schema_changed';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(manifest->'tables') LOOP
  IF entry->>'ownership_adapter'='financial_entry_customer' AND entry->>'table'='sandy_commerce_entry_lines' THEN owner_predicate:='EXISTS(SELECT 1 FROM public.sandy_commerce_entries parent WHERE parent.id=t.entry_id AND parent.customer_id=$1)'; ELSIF entry->>'ownership_adapter'='financial_statement_customer' AND entry->>'table'='sandy_commerce_statement_lines' THEN owner_predicate:='EXISTS(SELECT 1 FROM public.sandy_commerce_statements parent WHERE parent.id=t.statement_id AND parent.customer_id=$1)'; ELSIF entry->>'ownership_adapter'='support_case_customer' AND entry->>'table'='sandy_product_support_comments' THEN owner_predicate:='EXISTS(SELECT 1 FROM public.sandy_product_support_cases parent WHERE parent.id=t.case_id AND parent.customer_id=$1)'; ELSE owner_predicate:=format('t.%I=$1',entry->>'owner_column');END IF;
  SELECT string_agg(format('t.%I%s',k.value,CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(entry->'columns')c WHERE c->>'name'=k.value AND c->>'type'='text') THEN ' COLLATE "C"' ELSE '' END),',' ORDER BY k.position) INTO order_sql FROM jsonb_array_elements_text(entry->'order') WITH ORDINALITY k(value,position);
  EXECUTE format('SELECT count(*) FROM(SELECT 1 FROM public.%I t WHERE %s LIMIT 50001)q',entry->>'table',owner_predicate) INTO row_count USING p_tenant;
  IF row_count>50000 THEN RAISE EXCEPTION 'tenant_content_table_row_bound_exceeded';END IF;
  projection:='';size_sql:='';
  FOR col IN SELECT value FROM jsonb_array_elements(entry->'columns') LOOP
   projection:=projection||CASE WHEN projection='' THEN '' ELSE ',' END||format('%L,t.%I%s',col->>'name',col->>'name',CASE WHEN col->>'encoding'='decimal_integer_string' THEN '::text' ELSE '' END);
   size_sql:=size_sql||CASE WHEN size_sql='' THEN '' ELSE '+' END||format('coalesce(octet_length(t.%I::text),0)',col->>'name');
  END LOOP;
  IF p_manifest='customer_financial_fragments_v1' THEN
   FOR col IN SELECT value FROM jsonb_array_elements(entry->'columns') LOOP
    IF col->>'encoding'='decimal_integer_string' THEN
     EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I t WHERE (%s) AND t.%I::text !~ %L)',entry->>'table',owner_predicate,col->>'name','^-?(0|[1-9][0-9]*)$') INTO oversize USING p_tenant;
     IF oversize THEN RAISE EXCEPTION 'tenant_financial_nonfinite_decimal_refused';END IF;
    ELSIF col->>'type'='timestamp with time zone' THEN
     EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I t WHERE (%s) AND NOT isfinite(t.%I))',entry->>'table',owner_predicate,col->>'name') INTO oversize USING p_tenant;
     IF oversize THEN RAISE EXCEPTION 'tenant_financial_nonfinite_timestamp_refused';END IF;
    END IF;
   END LOOP;
  END IF;
  -- Bound source field bytes before building a potentially large JSON row.
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I t WHERE (%s) AND (%s)>16777216)',entry->>'table',owner_predicate,size_sql) INTO oversize USING p_tenant;
  IF oversize THEN RAISE EXCEPTION 'tenant_content_row_byte_bound_exceeded';END IF;
  IF entry->>'table'='sandy_product_graph_drafts' THEN
   IF EXISTS(SELECT 1 FROM public.sandy_product_graph_drafts draft LEFT JOIN public.email_messages message ON message.id=draft.source_message_id AND message.customer_id=p_tenant WHERE draft.customer_id=p_tenant AND draft.source_message_id IS NOT NULL AND message.id IS NULL) THEN RAISE EXCEPTION 'tenant_content_draft_source_ownership_refused';END IF;
   IF EXISTS(SELECT 1 FROM public.sandy_product_graph_drafts draft WHERE draft.customer_id=p_tenant AND CASE WHEN jsonb_typeof(draft.recipients)='array' THEN jsonb_array_length(draft.recipients)>21 ELSE true END) THEN RAISE EXCEPTION 'tenant_content_draft_recipients_projection_refused';END IF;
   IF EXISTS(SELECT 1 FROM public.sandy_product_graph_drafts draft CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN draft.customer_id=p_tenant AND jsonb_typeof(draft.recipients)='array' THEN draft.recipients ELSE '[]'::jsonb END) recipient(value) WHERE draft.customer_id=p_tenant AND (jsonb_typeof(recipient.value)<>'string' OR char_length(recipient.value#>>'{}')>254)) THEN RAISE EXCEPTION 'tenant_content_draft_recipients_projection_refused';END IF;
  END IF;
  IF entry->>'table'='sandy_commerce_entry_lines' AND EXISTS(SELECT 1 FROM public.sandy_commerce_entry_lines l JOIN public.sandy_commerce_entries e ON e.id=l.entry_id AND e.customer_id=p_tenant LEFT JOIN public.sandy_commerce_accounts a ON a.id=l.account_id AND a.customer_id=p_tenant WHERE a.id IS NULL) THEN RAISE EXCEPTION 'tenant_financial_parent_ownership_refused';END IF;
  IF entry->>'table'='sandy_commerce_entries' AND EXISTS(SELECT 1 FROM public.sandy_commerce_entries e LEFT JOIN public.sandy_commerce_entries parent ON parent.id=e.reversal_of AND parent.customer_id=p_tenant WHERE e.customer_id=p_tenant AND e.reversal_of IS NOT NULL AND parent.id IS NULL) THEN RAISE EXCEPTION 'tenant_financial_parent_ownership_refused';END IF;
  IF entry->>'table'='sandy_commerce_statements' AND EXISTS(SELECT 1 FROM public.sandy_commerce_statements s LEFT JOIN public.sandy_commerce_accounts a ON a.id=s.account_id AND a.customer_id=p_tenant WHERE s.customer_id=p_tenant AND a.id IS NULL) THEN RAISE EXCEPTION 'tenant_financial_parent_ownership_refused';END IF;
  IF entry->>'table'='sandy_commerce_reconciliations' THEN
   IF EXISTS(SELECT 1 FROM public.sandy_commerce_reconciliations rec LEFT JOIN public.sandy_commerce_statements s ON s.id=rec.statement_id AND s.customer_id=p_tenant WHERE rec.customer_id=p_tenant AND s.id IS NULL) THEN RAISE EXCEPTION 'tenant_financial_parent_ownership_refused';END IF;
   IF EXISTS(SELECT 1 FROM public.sandy_commerce_reconciliations rec WHERE rec.customer_id=p_tenant AND NOT public.sandy_tenant_financial_json_valid('sandy_commerce_reconciliations',rec.matches,p_tenant,rec.statement_id)) THEN RAISE EXCEPTION 'tenant_financial_json_projection_refused';END IF;
  END IF;
  IF entry->>'table'='sandy_commerce_invoices' THEN
   IF EXISTS(SELECT 1 FROM public.sandy_commerce_invoices inv LEFT JOIN public.email_messages message ON message.id=inv.source_message_id AND message.customer_id=p_tenant WHERE inv.customer_id=p_tenant AND inv.source_message_id IS NOT NULL AND message.id IS NULL) THEN RAISE EXCEPTION 'tenant_financial_parent_ownership_refused';END IF;
   IF EXISTS(SELECT 1 FROM public.sandy_commerce_invoices inv WHERE inv.customer_id=p_tenant AND NOT public.sandy_tenant_financial_json_valid('sandy_commerce_invoices',inv.items,p_tenant,NULL)) THEN RAISE EXCEPTION 'tenant_financial_json_projection_refused';END IF;
  END IF;
  query:=format('SELECT jsonb_build_object(%s)::text AS value FROM public.%I t WHERE %s ORDER BY %s',projection,entry->>'table',owner_predicate,order_sql);
  stream_buffer:='';table_sequence:=0;table_rows:=0;row_chain:=encode(extensions.digest(manifest->>'manifest_sha256'||':'||(entry->>'table'),'sha256'),'hex');
  FOR row_data IN EXECUTE query USING p_tenant LOOP
   row_text:=row_data.value||E'\n';
   IF octet_length(row_text)>16777216 THEN RAISE EXCEPTION 'tenant_content_row_byte_bound_exceeded';END IF;
   total_bytes:=total_bytes+octet_length(row_text);table_rows:=table_rows+1;
   IF total_bytes>134217728 OR table_rows>50000 THEN RAISE EXCEPTION 'tenant_content_snapshot_bound_exceeded';END IF;
   row_chain:=encode(extensions.digest(row_chain||E'\n'||row_text,'sha256'),'hex');stream_buffer:=stream_buffer||row_text;
   WHILE char_length(stream_buffer)>=65536 LOOP
    IF sequence_number>=2048 THEN RAISE EXCEPTION 'tenant_content_fragment_bound_exceeded';END IF;
    RETURN NEXT jsonb_build_object('manifest',manifest->>'id','manifest_sha256',manifest->>'manifest_sha256','tenant_id',p_tenant,'table',entry->>'table','sequence',sequence_number,'table_sequence',table_sequence,'table_complete',false,'table_row_count',NULL,'table_row_chain_sha256',NULL,'json_fragment',left(stream_buffer,65536));
    stream_buffer:=substring(stream_buffer FROM 65537);sequence_number:=sequence_number+1;table_sequence:=table_sequence+1;
   END LOOP;
  END LOOP;
  -- Every table ends with an explicit completion fragment, including empty
  -- tables and exact-boundary streams. Empty fragments preserve final digests.
  IF sequence_number>=2048 THEN RAISE EXCEPTION 'tenant_content_fragment_bound_exceeded';END IF;
  RETURN NEXT jsonb_build_object('manifest',manifest->>'id','manifest_sha256',manifest->>'manifest_sha256','tenant_id',p_tenant,'table',entry->>'table','sequence',sequence_number,'table_sequence',table_sequence,'table_complete',true,'table_row_count',table_rows,'table_row_chain_sha256',row_chain,'json_fragment',stream_buffer);
  sequence_number:=sequence_number+1;
 END LOOP;
 RETURN;
END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_content_capture_v1(p_tenant uuid) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ SELECT * FROM public.sandy_tenant_fragment_capture_v1(p_tenant,'customer_content_fragments_v1') $$;
CREATE FUNCTION public.sandy_tenant_financial_capture_v1(p_tenant uuid) RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ SELECT * FROM public.sandy_tenant_fragment_capture_v1(p_tenant,'customer_financial_fragments_v1') $$;
REVOKE ALL ON FUNCTION public.sandy_tenant_financial_manifest_v1(),public.sandy_tenant_financial_schema_sha256(),public.sandy_tenant_financial_json_valid(text,jsonb,uuid,uuid),public.sandy_tenant_fragment_capture_v1(uuid,text),public.sandy_tenant_content_capture_v1(uuid),public.sandy_tenant_financial_capture_v1(uuid) FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
